        "check_cluster_data",
        "check_cluster_structure"
    ]
}

def check_file_exists(filepath):
    """Check if a file exists"""
    return filepath.exists()

def check_file_content(filepath, min_rows=1):
    """Check if file has at least min_rows rows"""
    if not filepath.exists():
        return False, "File does not exist"

    try:
        with open(filepath, 'r') as f:
            lines = f.readlines()
            return len(lines) >= min_rows, f"File has {len(lines)} lines, expected at least {min_rows}"
    except Exception as e:
        return False, f"Error reading file: {str(e)}"

def validate_indicator_columns(filepath):
    """Validate columns in t01_selected_indicators.csv"""
    try:
        with open(filepath, 'r') as f:
            reader = csv.DictReader(f)
            return list(reader.keys()) == ['indicator_id', 'indicator_name', 'theme', 'justification', 'expected_direction']
    except Exception as e:
        return False, str(e)

def validate_indicator_data(filepath):
    """Validate data in t01_selected_indicators.csv"""
    try:
        with open(filepath, 'r') as f:
            reader = csv.DictReader(f)
            has_valid_data = True
            for row in reader:
                if not row.get('indicator_id'):
                    has_valid_data = False
                    break
            return has_valid_data
    except Exception as e:
        return False, str(e)

def check_file_columns(filepath):
    """Check that required columns exist"""
    required_columns = ['indicator_id', 'indicator_name', 'theme', 'justification', 'expected_direction']
    try:
        with open(filepath, 'r') as f:
            reader = csv.reader(f)
            header = next(reader)
            return all(col in header for col in required_columns)
    except Exception as e:
        return False, str(e)

def check_file_structure(filepath):
    """Check file structure"""
    try:
        with open(filepath, 'r') as f:
            lines = f.readlines()
            return len(lines) > 0
    except Exception as e:
        return False, str(e)

def main():
    """Main validation function"""
    summary = {
        "checks": [],
        "timestamp": "2024-01-01T00:00:00"
    }

    for file_path in REQUIRED_FILES:
        full_path = INPUTS_DIR / file_path
        exists, message = check_file_exists(full_path)
        if not exists:
            summary["checks"].append({
                "check_name": f"File Exists: {file_path}",
                "passed": False,
                "message": message
            })
            continue

        has_content, message = check_file_content(full_path, min_rows=1)
        if not has_content:
            summary["checks"].append({
                "check_name": f"File Content: {file_path}",
                "passed": False,
                "message": message
            })
