        has_columns, message = check_file_columns(full_path)
        if not has_columns:
            summary["checks"].append({
                "check_name": f"Columns: {file_path}",
                "passed": False,
                "message": message
            })
            continue

        has_structure, message = check_file_structure(full_path)
        if not has_structure:
            summary["checks"].append({
                "check_name": f"Structure: {file_path}",
                "passed": False,
                "message": message
            })
            continue

        summary["checks"].append({
            "check_name": f"File Validation: {file_path}",
            "passed": True,
            "message": "File exists and has valid structure"
        })

    # Write summary
    output_path = OUTPUTS_DIR / "validation_summary.json"
    with open(output_path, 'w') as f:
        json.dump(summary, f, indent=2)

    print(f"Validation complete. Summary written to {output_path}")

    return 0

if __name__ == "__main__":
    exit(main())
